39:     const key = line.slice(0, separator).trim();
40:     if (!key) continue;
41:     let value = line.slice(separator + 1).trim();
42:     if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
43:       value = value.slice(1, -1);
44:     }
45:     if (value.startsWith('[') && value.endsWith(']')) {
46:       data[key] = value.slice(1, -1).split(',').map((tag) => tag.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
47:     } else {
48:       data[key] = value;
49:     }
50:   }
51:   return data;
